        a: 'El trekking se realiza por senderos forestales que pueden ser escarpados e irregulares, ascendiendo desde el nivel del lago a 773 m (2.536 pies) hacia crestas cercanas a 1.500 m (4.921 pies). La caminata para encontrar a los chimpancés puede llevar entre treinta minutos y unas horas según dónde se haya desplazado la comunidad durante la noche. Una condición física razonable ayuda, pero es un trekking de aventura, no técnico ni extremo — la mayoría de los viajeros en buen estado general lo manejan cómodamente.',
