    overview: [
      "Existe una diferencia entre ver fauna y estar posicionado para ella — y esa diferencia es toda la premisa de este itinerario. Siete días a través de tres ecosistemas, cada uno elegido no solo por lo que vive allí sino por lo que permite hacer con una cámara o una genuina curiosidad: las manadas de elefantes de Tarangire moviéndose bajo baobabs milenarios, un encuentro cultural masái y la ciudad comercial de Mto wa Mbu, un descenso completo al mundo cerrado del cráter del Ngorongoro que alberga casi 30.000 animales, y tres días en las llanuras de hierba corta de Ndutu durante la temporada de parto, cuando hasta 8.000 crías de ñu nacen en un solo día y cada depredador del ecosistema lo sabe.",
      "Esto está construido para dos tipos de viajeros que se superponen: el fotógrafo que quiere un guía que lea la luz y el comportamiento animal tan de cerca como el terreno, y el viajero orientado a la aventura que prefiere pasar tiempo real en menos lugares en lugar de correr entre una lista de parques. Disponible en dos niveles — Wilderness Reserve y Wilderness Sovereign — siguiendo la misma ruta de siete días, con el nivel de campamento cambiando bajo sus pies.",
    ],
