        a: 'Sí — este itinerario está diseñado específicamente para evitar la trampa de una parada de una sola noche en cada parque. Dos días completos en el Mara y dos más en Amboseli le dan tiempo real sobre el terreno en ambos, con un lago del Valle del Rift como un cambio de ritmo deliberado en medio, en lugar de un paso apresurado.',
